import requests, xml.etree.ElementTree as ET
pmid='25452875'
xml=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':pmid,'retmode':'xml'},timeout=20).text
root=ET.fromstring(xml)
for tag in ['ArticleTitle','AbstractText','Journal','PubDate','AuthorList']:
    vals=[]
    for e in root.iter(tag):
        vals.append(''.join(e.itertext()).strip())
    if vals: print(tag,':', ' || '.join(vals))
print('PMID:',pmid)
for url in [f'https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=EXT_ID:{pmid}&format=json',f'https://www.ebi.ac.uk/europepmc/webservices/rest/{pmid}/fullTextXML']:
    r=requests.get(url,timeout=20)
    print('URL',url,'STATUS',r.status_code,'LEN',len(r.text))
    if 'search?' in url: print(r.text[:3000])
    else: print(r.text[:1000])
